function sees(c:Car,target:Car){const p=c.mesh.position,q=target.mesh.position,dy=q.y-p.y;const visibleCover=solids.filter(r=>{const t=segmentHit(p.x,p.z,q.x-p.x,q.z-p.z,r,0);return t!==null&&p.y+1.5+dy*t>=(r.minY??-Infinity)&&p.y+1.5+dy*t<=(r.maxY??Infinity);});return target.alive&&hasSight(p.x,p.z,q.x,q.z,vehicles[c.loadout].vision,visibleCover)&&bridgeHit(p.x,p.y+1.5,p.z,q.x-p.x,dy,q.z-p.z)===null;}
function playerSees(target:Car){const viewer=player.alive?player:cars.find(c=>c.alive&&c.team===player.team);return target.team===player.team||!!viewer&&sees(viewer,target);}
function autoTarget(c:Car){return cars.filter(o=>o.alive&&o.team!==c.team&&o.invulnerable<=0&&sees(c,o)&&o.mesh.position.distanceTo(c.mesh.position)<=weapons[c.weapon].range).sort((a,b)=>a.mesh.position.distanceToSquared(c.mesh.position)-b.mesh.position.distanceToSquared(c.mesh.position))[0];}
