addEventListener('keydown',e=>{if(!running||paused)return;keys.add(e.code);if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyR'&&!running)reset();});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',clearInput);
function wheelAngle(e:PointerEvent){const r=wheel.getBoundingClientRect();return Math.atan2(e.clientY-r.top-r.height/2,e.clientX-r.left-r.width/2);}
wheel.addEventListener('pointerdown',e=>{if(wheelId!==null)return;wheelId=e.pointerId;lastWheelAngle=wheelAngle(e);wheel.setPointerCapture(e.pointerId);});
wheel.addEventListener('pointermove',e=>{if(e.pointerId!==wheelId)return;const a=wheelAngle(e),delta=Math.atan2(Math.sin(a-lastWheelAngle),Math.cos(a-lastWheelAngle));lastWheelAngle=a;wheelRotation=THREE.MathUtils.clamp(wheelRotation+delta,-.95,.95);steering=wheelRotation/.95;rim.style.transform=`rotate(${wheelRotation}rad)`;});
