const palettes=paintColors;document.querySelectorAll<HTMLButtonElement>('[data-skin]').forEach((b,i)=>b.addEventListener('click',()=>{if(!profileStore.paint(i)){menuToast('零件不足，完成战斗可以获取');return;}(player.mesh.userData.paint as THREE.MeshStandardMaterial).color.setHex(palettes[i]);player.mesh.userData.basePaint=palettes[i];renderUI();}));
let audio:AudioContext|null=null,muted=false,engineOsc:OscillatorNode|null=null,engineGain:GainNode|null=null;document.querySelector('#mute')!.addEventListener('click',()=>{muted=!muted;document.querySelector('#mute')!.textContent=muted?'音效 关':'音效 开';});function beep(freq:number,dur:number){if(muted||!audio)return;try{const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sawtooth';osc.frequency.setValueAtTime(freq,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(Math.max(40,freq*.4),audio.currentTime+dur);gain.gain.setValueAtTime(.035*profileStore.data.settings.volume/100,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);osc.connect(gain).connect(audio.destination);osc.start();osc.stop(audio.currentTime+dur);}catch{}}
function ensureEngine(){if(!audio||engineOsc)return;try{engineOsc=audio.createOscillator();engineGain=audio.createGain();engineOsc.type='triangle';engineOsc.frequency.value=45;engineGain.gain.value=0;engineOsc.connect(engineGain).connect(audio.destination);engineOsc.start();}catch{}}
let explosionNoise:AudioBuffer|null=null;
function explosionSound(position:THREE.Vector3){if(muted||!audio||position.distanceTo(player.mesh.position)>42)return;try{if(!explosionNoise){explosionNoise=audio.createBuffer(1,Math.floor(audio.sampleRate*.4),audio.sampleRate);const data=explosionNoise.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);}const source=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();source.buffer=explosionNoise;filter.type='lowpass';filter.frequency.value=650;gain.gain.setValueAtTime(.16*profileStore.data.settings.volume/100/(1+position.distanceTo(player.mesh.position)/18),audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.4);source.connect(filter).connect(gain).connect(audio.destination);source.start();source.stop(audio.currentTime+.4);}catch{}}
let paused=false,battleStats={damage:0,shots:0,deaths:0},record=0;try{record=Number(localStorage.getItem('arena-best'))||0;}catch{}document.querySelector('#record')!.textContent=`本机最高积分 ${record}`;
function setPaused(value:boolean){if(!running)return;paused=value;clearInput();document.querySelector<HTMLElement>('#pauseLayer')!.style.display=paused?'flex':'none';last=performance.now();if(paused)void audio?.suspend();else void audio?.resume();}
