function strikeAt(owner:Car,x:number,z:number){for(const [dx,dz] of [[0,0],[-3.5,1.5],[3.5,-1.5]]){const tx=THREE.MathUtils.clamp(x+dx,-46,46),tz=THREE.MathUtils.clamp(z+dz,-46,46),mesh=new THREE.Mesh(new THREE.RingGeometry(.2,3.3,40),new THREE.MeshBasicMaterial({color:0xff7046,side:THREE.DoubleSide,transparent:true,opacity:.3,depthWrite:false}));mesh.geometry.rotateX(-Math.PI/2);const v=mesh.geometry.attributes.position;for(let i=0;i<v.count;i++)v.setY(i,terrainHeight(tx+v.getX(i),tz+v.getZ(i))+.16);mesh.position.set(tx,0,tz);scene.add(mesh);warnings.push({mesh,ttl:1.1,duration:1.1,x:tx,z:tz,owner});}}
