function showPage(page:string){if(!['garage','armory','battle','career','settings','result'].includes(page))return;activePage=page;document.querySelectorAll<HTMLElement>('[data-page]').forEach(el=>el.hidden=el.dataset.page!==page);document.querySelectorAll<HTMLElement>('.dock-nav [data-nav]').forEach(el=>el.classList.toggle('selected',el.dataset.nav===page));renderUI();document.querySelector('#pages')!.scrollTop=0;}
function renderUI(){const d=profileStore.data,spec=vehicles[selectedCar],up=d.upgrades[selectedCar],gun=weapons[spec.weapon];d.weapon=spec.weapon;document.querySelector<HTMLElement>('.deploy-top')!.textContent=activePage==='battle'?'开始战斗 ▶':'出战 ▶';document.querySelector('#assetStatus')!.textContent=modelsReady?'3D MODELS / READY':assetProgress;document.querySelector('#profileRank')!.textContent=`LEVEL ${String(Math.floor(d.xp/200)+1).padStart(2,'0')} · ${d.wins>=5?'VETERAN':'ROOKIE'}`;document.querySelector('#coinsValue')!.textContent=d.coins.toLocaleString();document.querySelector('#xpValue')!.textContent=String(d.xp);document.querySelector('#vehicleName')!.textContent=spec.name.split(' / ')[0];document.querySelector('#vehicleRole')!.textContent=spec.role;document.querySelector('#vehicleDescription')!.textContent=spec.description;document.querySelector('#vehicleSkill')!.textContent=`${spec.skill} · ${spec.cooldown}秒冷却`;
 const stats=[['装甲',Math.round(spec.hp*(1+up.armor*.08)),330],['极速',+(spec.speed*(1+up.engine*.03)).toFixed(1),14],['单发伤害',Math.round(spec.damage*(1+up.weapon*.08)*gun.damage),120]];document.querySelector('#vehicleStats')!.innerHTML=stats.map(([label,value,max])=>`<div class="stat-row"><span>${label}</span><b>${value}</b><i><em style="width:${Math.min(100,Number(value)/Number(max)*100)}%"></em></i></div>`).join('');document.querySelector('#vehicleFallback')!.innerHTML=vehicleArt(selectedCar,`#${paintColors[d.paint].toString(16).padStart(6,'0')}`);document.querySelector<HTMLElement>('#vehicleFallback')!.style.visibility=webglAvailable?'hidden':'visible';document.querySelector('#upgradeRows')!.innerHTML=(['armor','engine','weapon'] as Upgrade[]).map((kind,i)=>`<div class="upgrade-row"><strong>${['装甲强化','动力调校','火力增幅'][i]} <small>${up[kind]}/5</small></strong><span>${['每级装甲 +8%','每级极速 +3%','每级伤害 +8%'][i]}</span><button data-upgrade="${kind}" ${up[kind]>=5||d.coins<150*(up[kind]+1)?'disabled':''}>${up[kind]>=5?'已满级':`⬡ ${150*(up[kind]+1)} ＋`}</button></div>`).join('');document.querySelector('#paintInfo')!.textContent=`${paintNames[d.paint]} · ${d.paint<3?'基础涂装':'车库涂装'} / 额外涂装每款 250 零件`;
 document.querySelectorAll<HTMLElement>('[data-skin]').forEach((el,i)=>{el.style.setProperty('--paint',`#${paintColors[i].toString(16).padStart(6,'0')}`);el.classList.toggle('selected',d.paint===i);});for(const [selector,key] of [['[data-car]','car'],['[data-weapon]','weapon'],['[data-arena]','arena']] as const)document.querySelectorAll<HTMLElement>(selector).forEach(el=>{const selected=Number(el.dataset[key])===(key==='car'?selectedCar:key==='weapon'?d.weapon:selectedArena);el.classList.toggle('selected',selected);if(key==='weapon')el.textContent=selected?'当前战车 ✓':'选择对应战车';});document.querySelectorAll<HTMLElement>('[data-mode]').forEach(el=>el.classList.toggle('selected',el.dataset.mode===selectedMode));document.querySelectorAll<HTMLElement>('[data-input]').forEach(el=>el.classList.toggle('selected',el.dataset.input===inputMode));document.querySelector('#modeHelp')!.textContent=modeHelp[selectedMode];document.querySelector('#arenaDescription')!.textContent=arenas[selectedArena].description;document.querySelector('#readyLoadout')!.textContent=`${spec.name.split(' / ')[0]} · ${gun.name} · ${spec.skill}`;document.querySelector('#loadoutSummary')!.textContent=`当前配置：${spec.name} / ${gun.name} / 伤害升级 ${up.weapon}/5`;
 weapons.forEach((w,i)=>{document.querySelector(`#weapon-stats-${i}`)!.innerHTML=[['伤害',Math.round(vehicles[i].damage*(1+profileStore.data.upgrades[i].weapon*.08))],['装填',`${(vehicles[i].reload).toFixed(2)}s`],['射程',`${w.range}m`],['视野',`${vehicles[i].vision}m`],['弹速',w.speed],['溅射',w.splash?`${w.splash}m`:'无']].map(([label,value])=>`<div class="weapon-stat"><span>${label}</span><b>${value}</b></div>`).join('');});document.querySelector('#careerStats')!.innerHTML=[['完成对局',d.games],['获胜',d.wins],['累计击毁',d.kills],['生存波次',`${d.bestWave}/6`]].map(([label,value])=>`<div class="career-stat"><strong>${value}</strong><span>${label}</span></div>`).join('');const milestones=[['first','初次出击','完成 1 场战斗',d.games,1,150],['hunter','废土猎手','累计击毁 25 辆敌车',d.kills,25,350],['veteran','常胜车手','赢得 5 场战斗',d.wins,5,500],['survivor','独行不败','完成单人生存 6 波',d.bestWave,6,800]] as const;document.querySelector('#milestones')!.innerHTML=milestones.map(([id,name,description,value,target,reward])=>`<div class="milestone"><h3>${name}</h3><p>${description} · ${Math.min(value,target)}/${target}</p><button class="metal-button" data-claim="${id}" ${d.claims.includes(id)||value<target?'disabled':''}>${d.claims.includes(id)?'已领取':`领取 ⬡ ${reward}`}</button><div class="progress-track"><i style="width:${Math.min(100,value/target*100)}%"></i></div></div>`).join('');
 document.querySelectorAll<HTMLInputElement|HTMLSelectElement>('[data-setting]').forEach(el=>{const key=el.dataset.setting as keyof typeof d.settings;if(el instanceof HTMLInputElement&&el.type==='checkbox')el.checked=!!d.settings[key];else el.value=String(d.settings[key]);});for(const key of ['sensitivity','controlScale','volume','zoom'] as const)document.querySelector(`#${key}Out`)!.textContent=String(d.settings[key]);applySettings();(player.mesh.userData.paint as THREE.MeshStandardMaterial).color.setHex(paintColors[d.paint]);player.mesh.userData.basePaint=paintColors[d.paint];}
function applySettings(){const settings=profileStore.data.settings;app.style.setProperty('--control-scale',String(settings.controlScale));renderer.setPixelRatio(Math.min(devicePixelRatio,settings.quality==='high'?2:settings.quality==='medium'?1.3:1));renderer.shadowMap.enabled=settings.quality==='high';resize();}
app.addEventListener('click',event=>{const button=(event.target as HTMLElement).closest<HTMLElement>('button');if(!button||running)return;if(button.classList.contains('deploy-top')&&activePage==='battle'){void beginBattle();return;}if(button.dataset.nav)showPage(button.dataset.nav);else if(button.dataset.upgrade){if(profileStore.upgrade(selectedCar,button.dataset.upgrade as Upgrade))menuToast('升级完成，下一场战斗生效');else menuToast('升级未完成：零件不足或已达上限');renderUI();}else if(button.dataset.weapon!==undefined){selectedCar=Number(button.dataset.weapon);profileStore.data.car=selectedCar;profileStore.data.weapon=vehicles[selectedCar].weapon;profileStore.save();renderUI();}else if(button.dataset.arena!==undefined){selectedArena=Number(button.dataset.arena);profileStore.data.arena=selectedArena;profileStore.save();renderUI();}else if(button.dataset.claim){if(profileStore.claim(button.dataset.claim))menuToast('里程碑奖励已领取');renderUI();}});
app.addEventListener('input',event=>{const input=event.target as HTMLInputElement,key=input.dataset.setting;if(!key)return;const d=profileStore.data.settings;if(key==='volume'||key==='sensitivity'||key==='controlScale'||key==='zoom')d[key]=Number(input.value);else if(key==='shake')d.shake=input.checked;else if(key==='quality')d.quality=input.value as typeof d.quality;else if(key==='difficulty')d.difficulty=input.value as typeof d.difficulty;profileStore.save();renderUI();});
document.querySelector('#fullscreen')!.addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else document.querySelector('#fullscreenHint')!.textContent='当前 Safari 不支持此全屏接口。横屏或添加到主屏幕可获得更大的画面。';}catch{document.querySelector('#fullscreenHint')!.textContent='此浏览器未允许全屏，仍可正常游玩。';}});
showPage('garage');

if(import.meta.env.PROD&&'serviceWorker' in navigator){void navigator.serviceWorker.register(assetPath('sw.js'),{scope:assetPath('')}).then(async()=>{await navigator.serviceWorker.ready;document.querySelector('#systemState')!.textContent='离线缓存就绪 · 本机自动保存';}).catch(()=>{document.querySelector('#systemState')!.textContent='本机存档 · 离线缓存暂不可用';});}

function applyLoadedAssets(){buildArena();for(const actor of cars){configureModel(actor.mesh,actor.loadout,actor.weapon);if(actor.mesh.userData.paint)(actor.mesh.userData.paint as THREE.MeshStandardMaterial).color.setHex(actor.player?paintColors[profileStore.data.paint]:vehicles[actor.loadout].color);}configureModel(preview,selectedCar,vehicles[selectedCar].weapon);for(const barrel of barrels){const source=assetTemplates.get('barrel');if(source){barrel.mesh.clear();barrel.mesh.add(fitAsset(instantiateAsset(source),1.2,1.4,1.2));}}for(let i=0;i<9;i++){const source=assetTemplates.get(['wreck-race','wreck-truck','wreck-sedan'][i%3]);if(!source)continue;const wreck=fitAsset(instantiateAsset(source),2.3,1.7,4);wreck.position.set(-54+(i%3)*6,0,-35+Math.floor(i/3)*18);wreck.rotation.y=i*.7;scene.add(wreck);}renderUI();}
if(typeof window!=='undefined'){syncViewport();window.visualViewport?.addEventListener('resize',syncViewport);window.visualViewport?.addEventListener('scroll',syncViewport);addEventListener('orientationchange',()=>{syncViewport();setTimeout(syncViewport,120);setTimeout(syncViewport,350);});addEventListener('pageshow',syncViewport);assetPromise=loadAssetLibrary((done,total)=>{assetProgress=`三维资源 ${done}/${total}`;document.querySelector('#assetStatus')!.textContent=assetProgress;}).then(ready=>{modelsReady=ready;if(ready)applyLoadedAssets();else document.querySelector('#assetStatus')!.textContent='模型未完整加载 · 请刷新重试';return ready;});}

const visionLines=[0x6fc5b6,0xc6a16b].map(color=>{const line=new THREE.LineLoop(new THREE.BufferGeometry().setAttribute('position',new THREE.BufferAttribute(new Float32Array(96*3),3)),new THREE.LineBasicMaterial({color,transparent:true,opacity:.14}));scene.add(line);return line;});
function updateVisionLines(){const viewer=player.alive?player:cars.find(c=>c.alive&&c.team===player.team)??player;visionLines.forEach((line,index)=>{line.visible=running;const radius=index===0?vehicles[viewer.loadout].vision:weapons[viewer.weapon].range,points=line.geometry.attributes.position;for(let j=0;j<96;j++){const a=j/96*Math.PI*2,x=viewer.mesh.position.x+Math.cos(a)*radius,z=viewer.mesh.position.z+Math.sin(a)*radius;points.setXYZ(j,x,terrainHeight(x,z)+.12,z);}points.needsUpdate=true;line.geometry.computeBoundingSphere();});}
